async function loadCatalogue(){if(!db){toast("Store connection failed to start. Refresh the page.");return}let lastError=null;for(let attempt=0;attempt<3;attempt++){let req=db.from("products").select("*").order("created_at",{ascending:false});if(!adminMode)req=req.eq("active",true);const {data,error}=await req;if(!error){products=(data||[]).map(normalize);refresh();return}lastError=error;console.error("Store catalogue request failed:",{attempt:attempt+1,message:error.message,code:error.code,details:error.details,hint:error.hint});if(attempt<2)await new Promise(resolve=>setTimeout(resolve,500*(attempt+1)))}if(!products.length){const grid=$("#productGrid"),home=$("#homeProducts");if(grid){grid.innerHTML="";const empty=$("#emptyState");if(empty){empty.hidden=false;empty.innerHTML='<h2>We could not load the catalogue.</h2><p>Check your connection and refresh the page in a moment.</p><button class="button button-dark" type="button" onclick="location.reload()">Try again ↻</button>'}}if(home)home.innerHTML="";}toast("Store connection failed after 3 attempts. Refresh to try again.");console.error("Final catalogue error:",lastError)}
