function renderShop(){const grid=$("#productGrid"),empty=$("#emptyState");if(!grid)return;let list=products.filter(isDogBottle).filter(p=>(p.name+" "+p.description+" portable dog water bottle turquoise pink").toLowerCase().includes(query)&&(category==="All"||category==="Pet Accessories"));const sort=$("#sortSelect")?.value||"featured";if(sort==="low")list.sort((a,b)=>a.price-b.price);if(sort==="high")list.sort((a,b)=>b.price-a.price);if(sort==="name")list.sort((a,b)=>a.name.localeCompare(b.name));if(sort==="featured")list.sort((a,b)=>Number(b.featured)-Number(a.featured));list=list.filter(p=>dogBottleColor(p)!=="Pink");grid.innerHTML=list.map(productCard).join("");const count=$("[data-product-count]");if(count)count.textContent=String(list.length).padStart(2,"0");if(empty)empty.hidden=list.length>0}
