function renderBag(){const roots=[$("#bagItems"),$("#bagDrawerItems")].filter(Boolean);bag=bag.filter(x=>product(x.id)&&isDogBottle(product(x.id))&&x.qty>0);saveBag();countBag();const quantity=bag.reduce((n,x)=>n+x.qty,0);const countLabel=quantity+" "+(quantity===1?"item":"items");if($("#bagItemCount"))$("#bagItemCount").textContent=countLabel;for(const root of roots){if(!bag.length){root.innerHTML='<div class="empty-state"><h2>Your bottle bag is empty.</h2><p>Choose turquoise or pink and get ready for your next walk.</p><a class="button button-dark" href="product.html?id=portable-dog-water-bottle-turquoise">Choose your bottle</a></div>'}else root.innerHTML=bag.map(x=>{const p=product(x.id),lineTotal=p.price*x.qty;return '<article class="bag-line"><img data-product-id="'+esc(p.id)+'" src="'+esc(p.image)+'" alt="'+esc(p.name)+'"><div class="bag-line-copy"><h3>'+esc(p.name)+'</h3><p class="bag-line-unit-price">'+money(p.price)+' <span>each</span></p><div class="qty-control"><button data-qty="'+esc(p.id)+'" data-delta="-1" aria-label="Decrease quantity of '+esc(p.name)+'"'+(x.qty<=1?' disabled':'')+'>−</button><span aria-label="Quantity">'+x.qty+'</span><button data-qty="'+esc(p.id)+'" data-delta="1" aria-label="Increase quantity of '+esc(p.name)+'">+</button></div><p class="bag-line-total">Item total · '+money(lineTotal)+'</p></div><button class="remove-item" data-remove="'+esc(p.id)+'" aria-label="Remove '+esc(p.name)+' from bag">Remove</button></article>'}).join('')}const total=bag.reduce((n,x)=>n+product(x.id).price*x.qty,0);["#bagSubtotal","#bagDrawerSubtotal"].forEach(sel=>{if($(sel))$(sel).textContent=money(total)});$("[data-drawer-count]").forEach(el=>el.textContent="("+quantity+")");renderBundleTotals()}
function renderBundleTotals(){
 const quantity=cartQuantity(bag),discount=bundleDiscount(quantity);
 const subtotalCents=bag.reduce((n,x)=>n+Math.round((Number(product(x.id)?.price)||0)*100)*x.qty,0);
 const total=Math.max(0,subtotalCents-discount*100)/100;
 document.querySelectorAll(".bag-summary-premium,.bag-bottom").forEach(root=>{
  if(!root.querySelector(".bundle-discount-line")){
   const rows='<div class="summary-line bundle-discount-line" hidden><span>Bundle savings</span><strong></strong></div><div class="summary-line bundle-total-line"><span>Total</span><strong></strong></div>';
   const anchor=root.querySelector(".bag-shipping-note")||root.querySelector("p");
   if(anchor)anchor.insertAdjacentHTML("beforebegin",rows);else root.insertAdjacentHTML("beforeend",rows);
  }
 });
 document.querySelectorAll(".bundle-discount-line").forEach(el=>{el.hidden=discount===0;const value=el.querySelector("strong");if(value)value.textContent="−"+money(discount)});
 document.querySelectorAll(".bundle-total-line").forEach(el=>{const value=el.querySelector("strong");if(value)value.textContent=money(total)});
}
function renderAdmin(){const root=$("#adminProductList");if(!root)return;const count=$("#adminProductCount");if(count)count.textContent=products.length+" products";root.innerHTML=products.length?products.map(p=>'<div class="admin-product-row"><img src="'+esc(p.image)+'" alt=""><div><strong>'+esc(p.name)+'</strong><small>'+money(p.price)+' · '+esc(p.category)+(p.featured?' · Featured':'')+'</small></div><div class="admin-row-actions"><button data-edit="'+esc(p.id)+'">Edit</button><button data-delete="'+esc(p.id)+'">Delete</button></div></div>').join():'<div class="empty-state"><p>No products added yet.</p><span>Products saved here appear across all devices.</span></div>'}

function renderOrders(){
const root=$("#adminOrdersList");if(!root)return;const summary=$("#ordersSummary"),paid=orders.filter(o=>o.payment_status==="COMPLETED"),outstanding=orders.filter(o=>o.fulfillment_status==="unfulfilled").length,revenue=paid.reduce((sum,o)=>sum+Number(o.amount||0),0);
if(summary)summary.innerHTML='<span><strong>'+paid.length+'</strong> paid orders</span><span><strong>'+new Intl.NumberFormat("sv-SE",{style:"currency",currency:"SEK"}).format(revenue)+'</strong> recorded sales</span><span><strong>'+outstanding+'</strong> to fulfil</span>';
if(!orders.length){root.innerHTML='<div class="empty-state"><h3>No paid orders yet.</h3><p>Completed PayPal payments will appear here automatically.</p></div>';return}
const statuses=[["unfulfilled","Unfulfilled"],["processing","Processing"],["shipped","Shipped"],["cancelled","Cancelled"]];
root.innerHTML=orders.map(o=>{const items=Array.isArray(o.items)?o.items:[],itemHtml=items.map(i=>'<li><span>'+esc(i.quantity)+' × '+esc(i.name)+'</span><span>'+esc(i.unit_amount||"")+' '+esc(i.currency_code||o.currency_code)+'</span></li>').join(""),options=statuses.map(([v,label])=>'<option value="'+v+'"'+(o.fulfillment_status===v?' selected':'')+'>'+label+'</option>').join(""),date=o.created_at?new Date(o.created_at).toLocaleString(navigator.language||"en-GB",{dateStyle:"medium",timeStyle:"short"}):"Date unavailable";
return '<article class="admin-order-card"><div class="admin-order-main"><div class="admin-order-top"><span class="admin-order-id">Order '+esc(o.paypal_order_id)+'</span><span class="admin-order-pill">Payment '+esc(o.payment_status)+'</span></div><div class="admin-order-meta"><span>'+esc(date)+'</span><span>'+esc(o.payer_email||"Buyer email unavailable")+'</span></div><ul class="admin-order-items">'+itemHtml+'</ul></div><div class="admin-order-actions"><strong class="admin-order-total">'+new Intl.NumberFormat("sv-SE",{style:"currency",currency:"SEK"}).format(Number(o.amount||0))+'</strong><label>Fulfilment status<select data-order-status="'+esc(o.id)+'">'+options+'</select></label><button type="button" class="button button-outline" data-save-order="'+esc(o.id)+'">Save status</button></div></article>'}).join("");
}
async function loadOrders(){if(!adminMode||!db)return;const root=$("#adminOrdersList");if(root)root.innerHTML='<div class="empty-state"><p>Loading recent orders…</p></div>';const {data,error}=await db.from("orders").select("*").order("created_at",{ascending:false}).limit(100);if(error){console.error("Could not load orders",error);if(root)root.innerHTML='<div class="empty-state"><h3>Orders could not load.</h3><p>Check the orders table migration and admin access policy.</p></div>';return}orders=data||[];renderOrders()}
async function saveOrderStatus(id){if(!adminMode)return toast("Admin approval required.");const select=$('[data-order-status="'+CSS.escape(id)+'"]');if(!select)return;const allowed=["unfulfilled","processing","shipped","cancelled"];if(!allowed.includes(select.value))return toast("Invalid fulfilment status.");const button=$('[data-save-order="'+CSS.escape(id)+'"]');if(button){button.disabled=true;button.textContent="Saving…"}const {error}=await db.from("orders").update({fulfillment_status:select.value,updated_at:new Date().toISOString()}).eq("id",id);if(button){button.disabled=false;button.textContent="Save status"}if(error){console.error(error);toast("Could not update fulfilment status. Check admin permissions.");return}orders=orders.map(o=>o.id===id?{...o,fulfillment_status:select.value,updated_at:new Date().toISOString()}:o);renderOrders();toast("Order fulfilment updated.")}

